const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const milestones = Array.isArray(deal.milestones) ? deal.milestones : [];
const now = new Date();
const closingDate = deal.closing_date ?? deal.critical_dates?.closing_date ?? null;
const closingDateObj = closingDate ? new Date(closingDate) : null;
const daysToClose = closingDateObj && !Number.isNaN(closingDateObj.getTime())
  ? Math.ceil((closingDateObj.getTime() - now.getTime()) / 86400000)
  : null;

const blockers = Array.isArray(deal.blockers) ? deal.blockers.filter(Boolean) : [];
const overdueMilestones = milestones.filter(m => {
  const due = m?.due_date ? new Date(m.due_date) : null;
  const status = String(m?.status ?? '').toLowerCase();
  return due && !Number.isNaN(due.getTime()) && due.getTime() < now.getTime() &&
    !['completed','complete','closed','cancelled','waived'].includes(status);
});

const readiness = {
  title: Boolean(deal.title?.ready ?? deal.title?.confirmed ?? String(deal.title?.status ?? '').toLowerCase() === 'ready'),
  attorney: Boolean(deal.attorney?.ready ?? deal.attorney?.confirmed ?? String(deal.attorney?.status ?? '').toLowerCase() === 'ready'),
  funding: Boolean(deal.funding?.ready ?? deal.funding?.confirmed ?? String(deal.funding?.status ?? '').toLowerCase() === 'ready'),
  buyer: Boolean(deal.buyer?.ready ?? deal.buyer?.confirmed ?? String(deal.buyer?.status ?? '').toLowerCase() === 'ready')
};

const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executed = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase() === 'executed';
const agreementEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);
const criticalDatePresent = Boolean(closingDateObj && !Number.isNaN(closingDateObj.getTime()));
const milestoneComplete = milestones.length > 0 && milestones.every(m =>
  ['completed','complete','closed','waived'].includes(String(m?.status ?? '').toLowerCase())
);

let status = 'on_track';
let severity = 'normal';
if (!identityComplete || !executed || !agreementEvidence || !criticalDatePresent) {
  status = 'blocked';
  severity = 'urgent';
} else if (blockers.length || overdueMilestones.length || Object.values(readiness).some(v => !v)) {
  status = 'attention_required';
  severity = overdueMilestones.length || daysToClose !== null && daysToClose <= 3 ? 'urgent' : 'high';
} else if (daysToClose !== null && daysToClose < 0) {
  status = 'attention_required';
  severity = 'urgent';
} else if (milestoneComplete) {
  status = 'completed';
  severity = 'normal';
}

return [{
  json: {
    ...input,
    workflow_id: 'WF-172',
    workflow_name: 'Closing Coordination → Critical Dates & Milestone Monitor',
    decision: {status,severity},
    closing_date: closingDate,
    days_to_close: daysToClose,
    readiness,
    milestone_count: milestones.length,
    overdue_milestone_count: overdueMilestones.length,
    overdue_milestones: overdueMilestones.map(m => ({id:m?.id ?? null,name:m?.name ?? null,due_date:m?.due_date ?? null,status:m?.status ?? null})),
    blockers,
    identity_complete: identityComplete,
    execution_state: deal.execution_state ?? deal.agreement?.execution_state ?? null,
    signed_evidence_present: agreementEvidence,
    milestone_complete: milestoneComplete,
    routing: status === 'completed'
      ? {next_workflow:'WF-137',reason:'All required closing milestones are complete; evaluate closing outcome.'}
      : status === 'attention_required' || status === 'blocked'
        ? {next_workflow:'WF-155',reason:'Closing milestone orchestration or escalation is required.'}
        : {next_workflow:'WF-126',reason:'Closing coordination remains on track; continue coordination.'}
  }
}];

const out = $json ?? {};
return [{
  json: {
    ...out,
    workflow_id: 'WF-172',
    result: 'closing_monitor_evaluated',
    next_workflow: out.routing?.next_workflow ?? 'WF-126'
  }
}];
